CREATE FUNCTION ws4_private.patient_active() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (SELECT 1 FROM public.profiles p
                 WHERE p.user_id=auth.uid() AND p.is_active IS TRUE);
$$;
CREATE FUNCTION ws4_private.in_scope(p_organisation_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (SELECT 1 FROM ws4_private.memberships m
    JOIN public.profiles p ON p.user_id=m.user_id
    WHERE m.user_id=auth.uid() AND m.organisation_id=p_organisation_id
      AND m.active IS TRUE AND p.is_active IS TRUE);
$$;
CREATE OR REPLACE FUNCTION public.corvia_is_dispatch_operator() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (SELECT 1 FROM ws4_private.memberships m
    JOIN public.profiles p ON p.user_id=m.user_id
    WHERE m.user_id=auth.uid() AND m.active IS TRUE AND p.is_active IS TRUE);
$$;
CREATE FUNCTION ws4_private.patient_route() RETURNS uuid
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_route uuid;
BEGIN
  SELECT r.organisation_id INTO v_route FROM ws4_private.patient_routes r
  JOIN public.profiles p ON p.user_id=r.user_id
  WHERE r.user_id=auth.uid() AND p.is_active IS TRUE;
  IF v_route IS NULL THEN
    RAISE EXCEPTION 'Synthetic development routing has not been provisioned'
      USING ERRCODE='42501';
  END IF;
  RETURN v_route;
END $$;


