     OR existing.tgtype<>19 OR existing.tgenabled<>'O'
     OR regexp_replace(existing.prosrc,'\s','','g') <>
        regexp_replace($body$BEGIN
          IF NEW.user_type != OLD.user_type THEN
            RAISE EXCEPTION 'user_type cannot be changed by the client';
          END IF;
